import { Component, inject, computed } from '@angular/core'; // Adicionado computed
import { CommonModule } from '@angular/common';
import { FinancialService } from '../../core/services/financial.service';
import { FinancialTableComponent } from '../../shared/components/financial-table/financial-table.component';
import { KpiCardComponent } from '../../shared/components/kpi-card/kpi-card.component';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FinancialTableComponent, KpiCardComponent],
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  financialService = inject(FinancialService);
  Object = Object;

  // ETAPA 6: Lógica para Pontos Positivos Dinâmicos
  pontosPositivos = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['margem_liquida'] > 10) items.push('✅ Margem Líquida sólida acima de 10%, indicando alta eficiência operacional.'); 
    if (ind['roa'] > 15) items.push('✅ Excelente retorno sobre ativos (ROA), demonstrando uso eficiente da estrutura.'); 
    
    // Verifica crescimento na Tabela DRE
    const lucroLiq = data.tabela_dre?.find(r => r.conta.toLowerCase().includes('lucro liq'));
    if (lucroLiq && lucroLiq.perc > 0) {
      items.push(`✅ Crescimento de ${lucroLiq.perc}% no Lucro Líquido comparado ao período anterior.`);
    }

    return items;
  });

  // ETAPA 6: Lógica para Pontos de Atenção Dinâmicos
  pontosAtencao = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const items: string[] = [];
    const ind = data.indices;

    if (ind['liq_corrente'] < 1.0) items.push('⚠️ Liquidez corrente abaixo de 1.0 indica risco imediato de insolvência.'); 
    if (ind['endiv_geral'] > 70) items.push('⚠️ Endividamento Geral crítico acima de 70%, comprometendo a autonomia financeira.'); 

    return items;
  });

  getAnosProcessados(anosObj: any): string {
    if (!anosObj) return '...';
    return Object.keys(anosObj).sort().join(' VS ');
  }

  formatKey(key: string): string {
    return key.replace(/_/g, ' ').toUpperCase();
  }

  getFormatType(key: string): 'currency' | 'percent' | 'number' {
    const k = key.toLowerCase();
    if (k.includes('margem') || k.includes('roa') || k.includes('perc') || k.includes('endiv')) return 'percent';
    if (k.includes('ebitda')) return 'currency';
    return 'number';
  }

  getDynamicDescription(key: string, value: any): string {
    const val = Number(value);
    if (key.includes('liq_corrente')) {
      if (val < 1.0) return '🚨 CRÍTICO: Dificuldade de pagar dívidas'; 
      if (val <= 1.5) return '⚠️ ATENÇÃO: Capacidade justa'; 
      return '✅ BOM: Capacidade adequada'; 
    }
    return 'Indicador processado via Emerald AI';
  }

  onFileSelected(event: any) {
    const files = event.target.files;
    if (files.length) {
      this.financialService.uploadFiles(Array.from(files)).subscribe({
        error: (err: any) => alert('Erro na análise: ' + (err.error?.error || 'Falha no servidor'))
      });
    }
  }

  print() { window.print(); } 
}
